const PROFILES = {
  u1: 'Ada Lovelace',
  u2: 'Grace Hopper',
};

const TEMPLATE = 'users/{user_id}/profile';

function extractUserId(uri) {
  // Accept both the bare template form and a scheme-prefixed form.
  const match = uri.match(/^users\/([^/]+)\/profile$/);
  if (match) return match[1];
  return null;
